 const make=(name,fragmentShader,uniforms)=>new T.RawShaderMaterial({name,glslVersion:T.GLSL3,vertexShader:vertex,fragmentShader,uniforms,depthTest:false,depthWrite:false,toneMapped:false,blending:T.NoBlending});const atmosphere=make('Half-resolution depth SSAO and spatial cone haze',fragment,u),merge=make('Depth-aware haze resolve',composite,{sourceColor:{value:null},auxMap:{value:null},depthMap:{value:null},size:{value:new T.Vector2()}}),quad=new T.Mesh(g,atmosphere);quad.frustumCulled=false;scene.add(quad);
